        unsigned char *data = (unsigned char *)v_allocate(v_size_mul((size_t)cap, v->size, f, l, c), f, l, c);
        if (v->length) memcpy(data, v->data, (size_t)v->length * v->size);
        v->data = data; v->capacity = cap;
