#endif
    if (length < 0 || (size_t)length >= sizeof(buffer)) v_panic(f, l, c, "Float64 formatting failed");
    copy = (char *)v_allocate((size_t)length + 1, f, l, c);
    memcpy(copy, buffer, (size_t)length + 1); return v_owned_text(copy, (size_t)length);
